CREATE OR REPLACE FUNCTION private.keep_quote_request_public_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.public_number is distinct from old.public_number then
    raise exception 'request_public_number_is_immutable';
  end if;
  return new;
end;
$function$

